import sys
input = sys.stdin.read

def count_balanced_striped_bsts(n):
    MOD = 998244353

    heights = []
    h = 0
    while (1 << h) - 1 <= n:
        heights.append((1 << h) - 1)
        h += 1

    if n not in heights:
        return 0

    def factorial_mod(m, mod):
        result = 1
        for i in range(2, m + 1):
            result = result * i % mod
        return result

    def n_choose_k_mod(n, k, mod):
        if k > n or k < 0:
            return 0
        return factorial_mod(n, mod) * pow(factorial_mod(k, mod), -1, mod) * pow(factorial_mod(n - k, mod), -1, mod) % mod

    if n % 2 == 0:
        half = n // 2
        return n_choose_k_mod(n, half, MOD)
    else:
        return 0

data = input().strip()
n = int(data)
result = count_balanced_striped_bsts(n)
print(result)
